const $=s=>document.querySelector(s), app=$('#app');let state=JSON.parse(localStorage.getItem('ems.session')||'null');const setTheme=mode=>{document.documentElement.dataset.theme=mode;localStorage.setItem('ems.theme',mode)};const applyPalette=p=>{if(!p)return;let root=document.documentElement,map={primary:'--theme-primary',secondary:'--theme-secondary',accent:'--theme-accent',main_background:'--theme-main-bg',surface_background:'--theme-surface',elevated_background:'--theme-elevated',main_text:'--theme-text',secondary_text:'--theme-secondary-text',muted_text:'--theme-muted',text_on_primary:'--theme-on-primary',button_background:'--theme-button',button_hover:'--theme-button-hover',border:'--theme-border',input_background:'--theme-input',focus_ring:'--theme-focus',divider:'--theme-divider',success:'--theme-success',warning:'--theme-warning',danger:'--theme-danger',info:'--theme-info',sidebar_background:'--theme-sidebar',sidebar_text:'--theme-sidebar-text',sidebar_active:'--theme-sidebar-active',header_background:'--theme-header',link_color:'--theme-link',page_background:'--theme-main-bg',glass_tint:'--glass-tint',glass_opacity:'--glass-opacity',glass_blur:'--glass-blur',glass_border_opacity:'--glass-border-opacity',error:'--theme-danger',classic_ink:'--classic-ink',classic_navy:'--classic-navy',classic_navy_deep:'--classic-navy-deep',classic_slate:'--classic-slate',classic_cream:'--classic-cream',classic_paper:'--classic-paper',classic_line:'--classic-line',classic_teal:'--classic-teal',classic_teal_dark:'--classic-teal-dark',classic_gold:'--classic-gold',classic_red:'--classic-red'};Object.entries(map).forEach(([k,v])=>p[k]&&root.style.setProperty(v,p[k]));root.dataset.themePackage='ocean';let classic=document.getElementById('classicThemeStylesheet');if(classic)classic.remove();localStorage.setItem('ems.theme.palette',JSON.stringify(p))};try{applyPalette(JSON.parse(localStorage.getItem('ems.theme.palette')||'null'))}catch{};setTheme(localStorage.getItem('ems.theme')||'light');const api=async(path,opt={})=>{let r=await fetch('/api/'+path,{...opt,headers:{'content-type':'application/json',...(state?{authorization:'Bearer '+state.token}:{}),...(opt.headers||{})}}),x=await r.json();if(!r.ok)throw Error(x.error||'Request failed');return x};const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=x=>{let n=Number(x||0);return Math.abs(n)>=1000?(n/1000).toLocaleString('en-BD',{maximumFractionDigits:1})+'K':n.toLocaleString('en-BD',{maximumFractionDigits:2})};const invoiceMoney=x=>Number(x||0).toLocaleString('en-BD',{minimumFractionDigits:2});const ago=x=>{let m=Math.max(0,Math.floor((Date.now()-new Date(x))/60000));return m<60?m+'m ago':m<1440?Math.floor(m/60)+'h ago':Math.floor(m/1440)+'d ago'};
let sessionTimer,permissionSyncedFor=null,entitlementSyncedFor=null;function toast(x){let e=$('#toast');e.textContent=x;e.style.display='block';setTimeout(()=>e.style.display='none',3000)}function sessionExpiry(token){try{return JSON.parse(atob(token.split('.')[1].replace(/-/g,'+').replace(/_/g,'/'))).exp*1000}catch{return 0}}function scheduleLogout(){clearTimeout(sessionTimer);if(!state?.token)return;let ms=sessionExpiry(state.token)-Date.now();if(ms<=0)return logout();sessionTimer=setTimeout(()=>{toast('Your session has expired. Please sign in again.');setTimeout(logout,900)},ms)}function save(s){state=s;localStorage.setItem('ems.session',JSON.stringify(s));scheduleLogout()}function logout(){clearTimeout(sessionTimer);localStorage.removeItem('ems.session');localStorage.removeItem('ems.admin.return');state=null;location.reload()}
async function verificationPage(token){app.innerHTML=`<main class="verifyPage"><section class="verifyCard"><p class="muted">Checking official EMS invoice record…</p></section></main>`;try{let d=await api('public/invoice/'+encodeURIComponent(token)),r=d.invoice,p=d.party,shop=r.stores,paid=Number(r.total_due)<=0;app.innerHTML=`<main class="verifyPage"><section class="verifyCard"><header class="invoicePrintHeader"><div class="invoiceShopInfo"><h2>${esc(shop.name)}</h2><p>${esc(shop.address||'')}</p><p>${esc(shop.phone||'')}${shop.phone2?' · '+esc(shop.phone2):''}</p><p>${esc(shop.email||'')}</p>${shop.website?`<p>${esc(shop.website)}</p>`:''}</div><div class="invoiceTitleRight"><small class="verifiedLabel">✓ OFFICIAL EMS VERIFICATION</small><h1>${r.kind==='sale'?'SALES INVOICE':'PURCHASE INVOICE'}</h1><span># ${esc(r.invoice_number)}</span><b class="invoiceStatus verified">Verified</b><em class="verifyPayment ${paid?'paid':'due'}">${paid?'Paid':'Payment due'}</em></div></header><div class="verifyCols"><div><h3>${r.kind==='sale'?'Bill to':'Supplier'}</h3><p><b>ID:</b> ${esc(p?.customer_code||p?.supplier_code||(r.custom_party_name?'Custom customer':'Custom / not registered'))}</p><p><b>Name:</b> ${esc(p?.name||r.custom_party_name||'—')}</p><p><b>Address:</b> ${esc(p?.address||r.custom_party_address||'—')}</p><p><b>Phone:</b> ${esc(p?.phone||r.custom_party_phone||'—')}</p></div><div><h3>Invoice details</h3><p><b>Date:</b> ${esc(r.invoice_date)}</p><p><b>Payment:</b> ${esc(r.payment_method)}</p><p><b>Transaction:</b> ${esc(r.transaction_id||'—')}</p></div></div><div class="tablewrap"><table class="printItems"><thead><tr><th>Item</th><th>Qty</th><th>Unit</th><th>Unit price</th><th>Total</th></tr></thead><tbody>${r.invoice_lines.map(x=>`<tr><td>${esc(x.inventory_items?.description||'Item')}<br><small>${esc(x.inventory_items?.item_code||'')}</small></td><td>${esc(x.quantity)}</td><td>${esc(x.inventory_items?.unit||'')}</td><td>${invoiceMoney(x.unit_price)}</td><td>${invoiceMoney(x.line_total)}</td></tr>`).join('')}</tbody></table></div><div class="verifyTotal"><p>Subtotal <b>${invoiceMoney(r.subtotal)}</b></p><p>Tax <b>${invoiceMoney(r.tax_amount)}</b></p><p>Discount <b>${invoiceMoney(r.discount)}</b></p><p>Paid <b>${invoiceMoney(r.paid_amount)}</b></p><p class="dueLine">Total due <b>${invoiceMoney(r.total_due)}</b></p></div><footer>Verified by EMS V1 · DoxTox</footer></section></main>`}catch(e){app.innerHTML=`<main class="verifyPage"><section class="verifyCard"><h1>Invoice not verified</h1><p class="muted">${esc(e.message)}</p><a href="/">Return to EMS</a></section></main>`}}
async function publicPage(page){app.innerHTML=`<header class="sitehead"><a class="wordmark" href="/"><b>EMS V1</b><small>powered by DoxTox</small></a><nav><a href="/#features">Features</a><a href="/#pricing">Pricing</a><a href="/?page=about">About</a><a href="/?page=blog">Blog</a><button class="secondary" id="publicAdmin">Administrator login</button><button id="publicShop">Shop login</button></nav></header><main class="publicPage" id="publicPage"><p class="muted">Loading…</p></main><footer><div class="wordmark"><b>EMS V1</b><small>powered by DoxTox</small></div><span>© ${new Date().getFullYear()} DoxTox.</span><span><a href="/?page=contact">Contact</a> · <a href="/?page=terms">Terms & Conditions</a></span></footer><div class="authlayer" id="authlayer" hidden></div>`;$('#publicAdmin').onclick=()=>showAuth('admin');$('#publicShop').onclick=()=>showAuth('shop');let root=$('#publicPage');try{if(page==='blog'){let posts=await api('public/blogs');root.innerHTML=`<section class="publicHero"><p class="eyebrow">EMS INSIGHTS</p><h1>Latest from EMS V1</h1><p>Product updates, retail operations advice, and business insights from DoxTox.</p></section><section class="blogGrid">${posts.length?posts.map(x=>`<article><div class="blogCover" ${x.cover_image_url?`style="background-image:url('${esc(x.cover_image_url)}')"`:''}></div><small>${new Date(x.published_at).toLocaleDateString()}</small><h2>${esc(x.title)}</h2><p>${esc(x.excerpt||'Read the latest EMS V1 update.')}</p><a href="/?page=blog-post&id=${x.id}">Read article →</a></article>`).join(''):'<p class="muted">No published articles yet.</p>'}</section>`}else if(page==='blog-post'){let post=await api('public/blogs?id='+encodeURIComponent(new URLSearchParams(location.search).get('id')));root.innerHTML=`<article class="articlePage">${post.cover_image_url?`<div class="articleCover" style="background-image:url('${esc(post.cover_image_url)}')"></div>`:''}<small>${new Date(post.published_at).toLocaleDateString()}</small><h1>${esc(post.title)}</h1><p class="articleExcerpt">${esc(post.excerpt||'')}</p><div class="articleBody">${esc(post.body).replace(/\n/g,'<br>')}</div></article>`}else if(page==='contact'){let [info,branding]=await Promise.all([api('public/page?slug=contact'),api('public/branding')]);root.innerHTML=`<section class="contactPage"><div class="contactInfo"><p class="eyebrow">CONTACT</p><h1>${esc(info.title)}</h1><div>${esc(info.body).replace(/\n/g,'<br>')}</div><h3>${esc(branding.website_name||'EMS V1')}</h3><p>${esc(branding.public_base_url||'')}</p></div><form class="contactForm" id="publicContact"><h2>Send us a message</h2><label>Name<input name="name" required></label><label>Email<input name="email" type="email" required></label><label>Phone<input name="phone"></label><label>Subject<input name="subject"></label><label>Message<textarea name="message" rows="6" required></textarea></label><button>Send message</button></form></section>`;$('#publicContact').onsubmit=async e=>{e.preventDefault();try{await api('public/contact',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});e.target.reset();toast('Your message was submitted successfully.')}catch(err){toast(err.message)}}}else{let p=await api('public/page?slug='+(page==='terms'?'terms':'about'));root.innerHTML=`<section class="aboutPage"><div><p class="eyebrow">${page==='terms'?'LEGAL':'ABOUT EMS'}</p><h1>${esc(p.title)}</h1><div class="articleBody">${esc(p.body).replace(/\n/g,'<br>')}</div></div><div class="aboutGraphic"><div class="graphicWindow"><span></span><span></span><span></span><b>EMS V1</b><i></i><i></i><i></i><em>Business clarity, every day.</em></div></div></section>`}}catch(e){root.innerHTML=`<section class="publicHero"><h1>Page unavailable</h1><p>${esc(e.message)}</p></section>`}}
function login(){let verifyToken=new URLSearchParams(location.search).get('verify'),publicRoute=new URLSearchParams(location.search).get('page');if(verifyToken)return verificationPage(verifyToken);if(publicRoute)return publicPage(publicRoute);app.innerHTML=`<header class="sitehead"><a class="wordmark" href="#top"><b data-brand-name>EMS V1</b><small>powered by <span data-powered-by>DoxTox</span></small></a><nav><a href="#features">Features</a><a href="#pricing">Pricing</a><a href="/?page=about">About</a><a href="/?page=blog">Blog</a><button class="secondary" id="adminLogin">Administrator login</button><button id="shopLogin">Shop login</button><button class="emslogin" id="emsLogin">EMS login</button></nav></header><main id="top" class="website"><section class="hero"><div><p class="eyebrow">MULTI-SHOP MANAGEMENT, MADE SIMPLE</p><h1>Run every part of your shop with clarity.</h1><p class="lead">EMS V1 gives owners and staff one secure place for inventory, purchases, sales, expenses, customers, and store operations.</p><div class="heroactions"><button id="heroStart">Create administrator account</button><button class="secondary" id="heroShop">Shop staff login</button></div><div class="trust"><span>✓ Custom secure credentials</span><span>✓ Cloud-based access</span><span>✓ BDT pricing</span></div></div><div class="heroart"><div class="screen"><div class="screenbar"><i></i><i></i><i></i></div><p>Today at a glance</p><div class="artcards"><b>৳ 24,860<small>Sales today</small></b><b>18<small>Low-stock items</small></b></div><div class="bars"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><span>Sales performance</span></div></div></section><section class="logos"><span>Built for retail shops</span><span>Grocery &amp; general stores</span><span>Pharmacy &amp; cosmetics</span><span>Electronics &amp; wholesale</span></section><section id="features" class="section"><p class="eyebrow">ONE SYSTEM, EVERYDAY OPERATIONS</p><h2>Everything a growing shop needs</h2><p class="sectionlead">Designed for shop owners who need accurate records, controlled staff access, and practical decisions—not complicated software.</p><div class="featuregrid"><article><div class="featureicon">▣</div><h3>Multi-store control</h3><p>Create and manage multiple stores from one administrator account. Check license status, activation, and connected devices.</p></article><article><div class="featureicon">▤</div><h3>Sales &amp; purchase invoices</h3><p>Prepare invoices, calculate tax, discount, paid amount, and due automatically while recording payment details.</p></article><article><div class="featureicon">◫</div><h3>Live inventory</h3><p>Stock changes when purchases or sales are posted. Low-stock indicators help you replenish before items run out.</p></article><article><div class="featureicon">♙</div><h3>Customers &amp; suppliers</h3><p>Keep contact details organized and quickly select a customer or supplier when creating invoices.</p></article><article><div class="featureicon">✓</div><h3>Staff permissions</h3><p>Create individual staff accounts and decide who can view, add, edit, or delete in each operational area.</p></article><article><div class="featureicon">◷</div><h3>Traceable activity</h3><p>Record operational activity, device logins, attendance, and system errors for stronger accountability.</p></article></div></section><section class="workflow"><div><p class="eyebrow">A CLEAR WORKFLOW</p><h2>From setup to sale in four steps</h2><ol><li><b>1</b><div><strong>Create your administrator account</strong><span>Set up your business profile with your own custom credentials.</span></div></li><li><b>2</b><div><strong>Add and activate a store</strong><span>Submit your license payment information for manual verification.</span></div></li><li><b>3</b><div><strong>Add staff, products, and contacts</strong><span>Control what each staff member can access.</span></div></li><li><b>4</b><div><strong>Record purchases and sales</strong><span>Let EMS update stock and financial totals as you work.</span></div></li></ol></div><aside><small>EMS V1 PROMISE</small><h3>Business records that stay organized.</h3><p>Use a single cloud-based workspace for daily shop operations, with access from approved devices.</p><button id="workflowAdmin">Get started as administrator</button></aside></section><section id="pricing" class="section pricing"><p class="eyebrow">STRAIGHTFORWARD PRICING</p><h2>Choose your license period</h2><p class="sectionlead">One store license per selected period. Submit bKash or Nagad payment details after creating a store; each claim is manually verified before activation.</p><div id="publicPricing" class="pricegrid"><p class="muted">Loading current EMS license plans…</p></div><p class="fineprint">Payment methods: bKash and Nagad. A transaction ID is required. Payments are subject to manual verification.</p></section><section class="cta"><div><h2>Ready to bring your shop operations together?</h2><p>Create an administrator account and set up your first store.</p></div><button id="ctaStart">Get started</button></section><section class="faq section"><p class="eyebrow">FREQUENTLY ASKED QUESTIONS</p><h2>Before you begin</h2><details><summary>Does EMS use Google, Facebook, or third-party login?</summary><p>No. Administrators and shop staff use custom EMS credentials stored through the application’s secure backend.</p></details><details><summary>When does a store become active?</summary><p>A store is activated after a license payment claim is manually checked and approved.</p></details><details><summary>Can I have different staff access levels?</summary><p>Yes. Staff permissions can be assigned per module for viewing, adding, editing, and deleting records.</p></details></section></main><footer><div class="wordmark"><b data-brand-name>EMS V1</b><small>powered by <span data-powered-by>DoxTox</span></small></div><span>© ${new Date().getFullYear()} DoxTox. All rights reserved.</span><a href="/?page=contact">Contact</a> · <a href="/?page=terms">Terms & Conditions</a></footer><div class="authlayer" id="authlayer" hidden></div>`;let open=m=>showAuth(m);['adminLogin','workflowAdmin','heroStart','ctaStart'].forEach(id=>$('#'+id).onclick=()=>open('admin'));['shopLogin','heroShop'].forEach(id=>$('#'+id).onclick=()=>open('shop'));$('#emsLogin').onclick=()=>showEmsLogin();document.querySelectorAll('[data-plan]').forEach(x=>x.onclick=()=>open('admin'));api('public/branding').then(b=>{document.title=(b.website_name||'EMS V1')+' | DoxTox';document.querySelectorAll('[data-brand-name]').forEach(x=>x.textContent=b.product_name||'EMS V1');document.querySelectorAll('[data-powered-by]').forEach(x=>x.textContent=b.powered_by||'DoxTox')}).catch(()=>{});api('public/license-plans').then(plans=>{let box=$('#publicPricing');box.innerHTML=plans.length?plans.map((p,i)=>`<article class="price ${i===1?'popular':''}">${i===1?'<em>Featured plan</em>':''}<h3>${esc(p.title)}</h3><strong>${Number(p.price)===0?'Free':money(p.price)}</strong><span>${p.duration_months} months · up to ${p.max_stores} shop${p.max_stores>1?'s':''}</span><ul>${(p.benefits||'').split(/\n|,/).filter(Boolean).map(x=>`<li>${esc(x.trim())}</li>`).join('')}<li>${p.connectx_enabled?`ConnectX: ${p.connectx_daily_limit} emails/day per shop`:'ConnectX not included'}</li></ul><button class="${i===1?'':'secondary'}" data-public-plan="${p.id}">Choose plan</button></article>`).join(''):'<p class="muted">No license plans are currently published.</p>';document.querySelectorAll('[data-public-plan]').forEach(x=>x.onclick=()=>open('admin'))}).catch(()=>{$('#publicPricing').innerHTML='<p class="muted">License plans are temporarily unavailable.</p>'})}
function showAuth(mode){let layer=$('#authlayer');layer.hidden=false;layer.innerHTML=`<div class="authmodal"><button class="close" id="closeAuth">×</button><p class="eyebrow">EMS V1 ACCESS</p><div class="tabs"><button class="${mode==='admin'?'on':''}" id="tabAdmin">Administrator</button><button class="${mode==='shop'?'on':''}" id="tabShop">Shop staff</button></div><form id="authform" class="fields">${mode==='admin'?`<h2>Administrator sign in</h2><label>Email<input name="email" type="email" required></label><label>Password<input name="password" type="password" minlength="10" required></label><button>Sign in</button><button class="linkbutton" type="button" id="register">Create administrator account</button>`:`<h2>Shop sign in</h2><label>4-digit Shop ID<input name="storeId" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" placeholder="Example: 1234" required></label><label>Staff User ID or Administrator Email<input name="userId" required></label><label>Password<input name="password" type="password" required></label><button>Sign in to shop</button>`}</form></div>`;$('#closeAuth').onclick=()=>{layer.hidden=true};$('#tabAdmin').onclick=()=>showAuth('admin');$('#tabShop').onclick=()=>showAuth('shop');let reg=$('#register');if(reg)reg.onclick=register;$('#authform').onsubmit=async e=>{e.preventDefault();try{let b=Object.fromEntries(new FormData(e.target));save(await api('auth/'+(mode==='admin'?'admin/login':'shop/login'),{method:'POST',body:JSON.stringify(b)}));home()}catch(x){toast(x.message)}}}
function showEmsLogin(){let layer=$('#authlayer');layer.hidden=false;layer.innerHTML=`<div class="authmodal"><button class="close" id="closeAuth">×</button><p class="eyebrow">PRIVATE PLATFORM ACCESS</p><form class="fields" id="emsform"><h2>EMS login</h2><p class="muted">For the EMS platform owner only.</p><label>Email<input name="email" type="email" required></label><label>Password<input name="password" type="password" required></label><button>Sign in to EMS control</button><button class="linkbutton" type="button" id="initializeOwner">Initialize first EMS owner</button></form></div>`;$('#closeAuth').onclick=()=>layer.hidden=true;$('#initializeOwner').onclick=()=>emsRegister();$('#emsform').onsubmit=async e=>{e.preventDefault();try{save(await api('auth/ems/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))}));home()}catch(x){toast(x.message)}}}
function emsRegister(){let layer=$('#authlayer');layer.innerHTML=`<div class="authmodal"><button class="close" id="closeAuth">×</button><p class="eyebrow">ONE-TIME INITIALIZATION</p><form class="fields" id="ownerform"><h2>Create EMS owner</h2><p class="muted">This is available only while no EMS owner exists. Use a private, strong password.</p><label>Name<input name="name" required></label><label>Email<input name="email" type="email" required></label><label>Password <span class="muted">(12+ characters)</span><input name="password" type="password" minlength="12" required></label><button>Initialize EMS owner</button><button class="linkbutton" type="button" id="backEms">Back to EMS login</button></form></div>`;$('#closeAuth').onclick=()=>layer.hidden=true;$('#backEms').onclick=showEmsLogin;$('#ownerform').onsubmit=async e=>{e.preventDefault();try{save(await api('auth/ems/register',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))}));home()}catch(x){toast(x.message)}}}
function register(){let layer=$('#authlayer');layer.hidden=false;layer.innerHTML=`<div class="authmodal"><button class="close" id="closeAuth">×</button><p class="eyebrow">START WITH EMS V1</p><form class="fields" id="reg"><h2>Create administrator account</h2><div class="grid2"><label>Full name<input name="name" required></label><label>Phone<input name="phone" required></label></div><label>Address<textarea name="address"></textarea></label><label>Email<input name="email" type="email" required></label><label>Password <span class="muted">(10+ characters)</span><input name="password" type="password" minlength="10" required></label><button>Create account</button><button type="button" class="linkbutton" id="backLogin">Back to sign in</button></form></div>`;$('#closeAuth').onclick=()=>layer.hidden=true;$('#backLogin').onclick=()=>showAuth('admin');$('#reg').onsubmit=async e=>{e.preventDefault();try{save(await api('auth/admin/register',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))}));home()}catch(x){toast(x.message)}}}
const menus=[['Dashboard','dashboard','▦'],['Suppliers','supplier','♟'],['Customers','customer','♚'],['Inventory','inventory','▣'],['Purchases','purchase','↓'],['Sales','sales','▤'],['Expense','expense','▤'],['Due Recover','due_recover','↗'],['Staff Manager','staff','♙'],['Report','report','▥'],['Settings','settings','⚙'],['ConnectX','connectx','✉'],['Zudo','zudo','✦']];const canAccess=(section,action='view')=>{if(state?.readOnly&&action!=='view'&&!((section==='connectx'&&action==='add')||(section==='zudo'&&action==='add')))return false;if(state?.role==='admin'||state?.adminAccess)return true;let p=state?.permissions||{},configured=Object.values(p).some(x=>Array.isArray(x)&&x.length);return !configured||(p[section]||[]).includes(action)};function home(){if(state?.role==='staff'&&permissionSyncedFor!==state.token){Promise.all([api('me'),api('connectx/availability').catch(()=>({enabled:false})),api('zudo/availability').catch(()=>({enabled:false})),api('business-health/availability').catch(()=>({enabled:false,ever:false}))]).then(([m,cx,zudo,bh])=>{state.permissions=m.permissions||{};state.readOnly=!!m.readOnly;state.licenseExpired=!!m.readOnly;state.connectxEnabled=!!cx.enabled;state.connectxHistory=!!cx.history;state.zudoEnabled=!!zudo.enabled;state.zudoHistory=!!zudo.history;state.businessHealthEnabled=!!bh.enabled;state.businessHealthEver=!!bh.ever;permissionSyncedFor=state.token;save(state);home()}).catch(e=>{toast(e.message);logout()});return}if(state?.role==='admin'&&entitlementSyncedFor!==state.token){api('admin/entitlement').then(x=>{state.licenseExpired=!!x.hasActivatedLicense&&!x.active;state.entitlement=x;entitlementSyncedFor=state.token;save(state);home()}).catch(e=>{toast(e.message);logout()});return}if(state.role==='owner')return ownerHome();let admin=state.role==='admin', visibleMenus=menus.filter(([,section])=>canAccess(section,'view')&&(section!=='connectx'||state.connectxEnabled||state.connectxHistory)&&(section!=='zudo'||state.zudoEnabled||state.zudoHistory));app.innerHTML=`<div class="shell"><aside class="sidebar ${admin?'adminSidebar':''}">${admin?'':`<div class="sidebarBrand"><b>EMS V1 · DoxTox</b><small>${esc(state.store?.name||'')}</small></div>`}<nav class="nav">${admin?'<button data-page="profile"><span class="menuicon">◉</span>My Profile</button><button data-page="stores"><span class="menuicon">▦</span>Store Manage</button><button data-page="licenses"><span class="menuicon">▤</span>Licenses</button><button data-page="devices"><span class="menuicon">⌘</span>Devices</button><button data-page="addons"><span class="menuicon">✦</span>Premium Add-Ons</button>':visibleMenus.map(([x,,icon])=>`<button data-page="${x.toLowerCase().replaceAll(' ','-')}"><span class="menuicon">${icon}</span>${x}</button>`).join('')}</nav>${admin?'':`<div class="sidebottom">${state.adminAccess?'<button class="secondary" id="returnAdmin">Return to admin</button>':''}<button class="logoutmenu" id="out">Logout</button></div>`}</aside><main class="main"><header class="top">${admin?`<div class="topBrand"><b>EMS V1 · DoxTox</b><small>Administrator dashboard</small></div>`:'<div class="topHeaderSpacer"></div>'}<div class="shopTopActions"><span class="topUser">${esc(state.user.name)}<span class="headerProfile">${esc(state.user.name).slice(0,1).toUpperCase()}</span></span>${!admin&&state.zudoEnabled&&canAccess('zudo','view')?'<button class="zudoTopButton" id="zudoTopButton" type="button" title="Open Zudo" aria-label="Open Zudo">✦</button>':''}${admin?'<button class="secondary" id="out">Logout</button>':`<label class="themeSwitch" title="Toggle light or dark appearance"><input id="themeToggle" type="checkbox" ${document.documentElement.dataset.theme==='dark'?'checked':''}><i></i><b>☀</b><b>☾</b></label>`}</div></header><section class="page" id="page"></section></main></div>`;$('#out').onclick=logout;if($('#themeToggle'))$('#themeToggle').onchange=e=>setTheme(e.target.checked?'dark':'light');if($('#zudoTopButton'))$('#zudoTopButton').onclick=()=>page('zudo');if($('#returnAdmin'))$('#returnAdmin').onclick=()=>{let r=JSON.parse(localStorage.getItem('ems.admin.return')||'null');if(r){save(r);localStorage.removeItem('ems.admin.return');home()}};document.querySelectorAll('[data-page]').forEach(x=>x.onclick=()=>page(x.dataset.page));page(admin?'stores':(visibleMenus[0]?.[0]||'dashboard').toLowerCase().replaceAll(' ','-'));if(state.licenseExpired)licenseExpiryPopup(admin)}
function licenseExpiryPopup(admin){if(document.querySelector('.licenseExpiryModal'))return;let e=document.createElement('div');e.className='modal licenseExpiryModal';e.innerHTML=`<section class="modalbox expiryNotice"><div class="expiryIcon">!</div><h2>License expired</h2><p>Your administrator license has expired. To continue operating shops, creating invoices, changing data, or using ConnectX, purchase and activate a new license.</p><p class="muted">Your shop data and license history are safely preserved. Shops are currently operating in Read-Only mode.</p>${admin?'<button id="goLicenses">View license plans</button>':'<button id="closeExpiry">Continue in Read-Only mode</button>'}</section>`;document.body.append(e);if(admin)$('#goLicenses').onclick=()=>{e.remove();page('licenses')};else $('#closeExpiry').onclick=()=>e.remove()}
function title(t,button=''){return `<div class="head"><div><h1>${t}</h1></div>${button}</div>`}async function page(p){document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===p));let el=$('#page');el.innerHTML='<p class="muted">Loading…</p>';try{if(p==='dashboard')return await dashboard();if(p==='profile')return await profile();if(p==='stores')return await stores();if(p==='licenses')return await licenses();if(p==='devices')return await devices();if(p==='addons')return await premiumAddons();if(['suppliers','customers','inventory','expense','staff-manager'].includes(p))return await entity(p);if(['purchases','sales'].includes(p))return await invoices(p);if(p==='due-recover')return await dueRecover();if(p==='report')return await report();if(p==='connectx')return await connectX();if(p==='zudo')return await zudo();if(p==='settings')return await settings();el.innerHTML=title(p.replaceAll('-',' '))+`<section class="panel"><p>This module is reserved for the next EMS update. It is intentionally not represented with fabricated records.</p></section>`}catch(e){el.innerHTML=`<section class="panel"><h2>Could not load this page</h2><p>${esc(e.message)}</p></section>`}}
function ownerHome(){app.innerHTML=`<div class="shell"><aside class="sidebar ownerSidebar"><nav class="nav"><button data-owner-page="overview"><span class="menuicon">▦</span>Overview</button><button data-owner-page="licenses"><span class="menuicon">▤</span>License control</button><button data-owner-page="plans"><span class="menuicon">▧</span>License plans</button><button data-owner-page="administrators"><span class="menuicon">♙</span>Administrators</button><button data-owner-page="shops"><span class="menuicon">▣</span>Shops</button><button data-owner-page="branding"><span class="menuicon">✦</span>Website branding</button><button data-owner-page="theme"><span class="menuicon">◌</span>Theme palette</button><button data-owner-page="website-pages"><span class="menuicon">▤</span>Website pages</button><button data-owner-page="blogs"><span class="menuicon">≡</span>Blogs</button><button data-owner-page="contact-messages"><span class="menuicon">✉</span>Contact messages</button><button data-owner-page="connectx"><span class="menuicon">✉</span>ConnectX</button><button data-owner-page="zudo"><span class="menuicon">✦</span>Zudo AI</button><button data-owner-page="addons"><span class="menuicon">✦</span>Premium Add-Ons</button><button data-owner-page="factory-reset"><span class="menuicon">!</span>Factory reset</button></nav></aside><main class="main"><header class="top"><div class="topBrand"><b>EMS V1 · DoxTox</b><small>EMS Platform Control</small></div><div class="shopTopActions"><span class="topUser">${esc(state.user.name)}<span class="headerProfile">${esc(state.user.name).slice(0,1).toUpperCase()}</span></span><button class="secondary" id="out">Logout</button></div></header><section class="page" id="page"></section></main></div>`;$('#out').onclick=logout;document.querySelectorAll('[data-owner-page]').forEach(x=>x.onclick=()=>ownerPage(x.dataset.ownerPage));ownerPage('overview')}
async function ownerPage(p){document.querySelectorAll('[data-owner-page]').forEach(x=>x.classList.toggle('active',x.dataset.ownerPage===p));let el=$('#page');el.innerHTML='<p class="muted">Loading platform data…</p>';try{let d=await api('platform/overview');if(p==='overview')return ownerOverview(d);if(p==='licenses')return ownerLicenses(d);if(p==='plans')return ownerPlans();if(p==='administrators')return ownerAdmins(d);if(p==='shops')return ownerShops(d);if(p==='branding')return ownerBranding();if(p==='theme')return ownerTheme();if(p==='website-pages')return ownerWebsitePages();if(p==='blogs')return ownerBlogs();if(p==='contact-messages')return ownerContactMessages();if(p==='connectx')return ownerConnectX();if(p==='zudo')return ownerZudo();if(p==='addons')return ownerAddons();if(p==='factory-reset')return ownerFactoryReset()}catch(e){el.innerHTML=`<section class="panel"><h2>Could not load platform control</h2><p>${esc(e.message)}</p></section>`}}
function ownerOverview(d){let active=d.licenses.filter(x=>x.status==='active').length,pending=d.licenses.filter(x=>x.status==='pending').length;$('#page').innerHTML=title('EMS platform overview')+`<div class="cards"><section class="card"><small>Administrators</small><strong>${d.admins.length}</strong></section><section class="card"><small>Shops</small><strong>${d.stores.length}</strong></section><section class="card"><small>Active licenses</small><strong>${active}</strong></section><section class="card"><small>Pending verification</small><strong>${pending}</strong></section></div><section class="panel"><h2>Pending license payments</h2>${table(d.licenses.filter(x=>x.status==='pending').map(x=>({shop:x.stores?.name,method:x.payment_method,amount:money(x.amount),transaction:x.transaction_id,submitted:x.created_at})),['shop','method','amount','transaction','submitted'])}</section>`}
function ownerLicenses(d){$('#page').innerHTML=title('License control')+`<section class="panel"><p class="muted">Approve only after verifying the transaction in the official bKash/Nagad merchant portal. Approval activates the related shop and sets its expiry date.</p><div class="tablewrap"><table><thead><tr><th>Administrator ID</th><th>Administrator</th><th>Shop</th><th>Type</th><th>Period</th><th>ConnectX</th><th>Amount</th><th>Payment</th><th>Number</th><th>Transaction ID</th><th>Status</th><th>Action</th></tr></thead><tbody>${d.licenses.map(x=>`<tr><td><code class="shopid">${esc(x.administrators?.admin_code||'—')}</code></td><td>${esc(x.administrators?.name||'—')}</td><td>${esc(x.stores?.name||'License capacity')}</td><td><span class="logaction">${esc(x.transaction_type||'new')}</span></td><td>${x.duration_months} months</td><td>${x.connectx_enabled?`${x.connectx_daily_limit}/shop/day`:'Not included'}</td><td>${money(x.amount)}</td><td>${esc(x.payment_method)}</td><td>${esc(x.payment_number)}</td><td>${esc(x.transaction_id)}</td><td><span class="statuspill ${x.status==='active'?'active':'inactive'}">${esc(x.status)}${x.transaction_type==='downgrade'&&x.starts_at&&new Date(x.starts_at)>new Date()?' · scheduled':''}</span></td><td class="actions">${x.status==='pending'?`<button data-approve="${x.id}">Approve</button><button class="danger" data-reject="${x.id}">Reject</button>`:'Reviewed'}</td></tr>`).join('')}</tbody></table></div></section>`;document.querySelectorAll('[data-approve]').forEach(b=>b.onclick=()=>reviewLicense(b.dataset.approve,'active'));document.querySelectorAll('[data-reject]').forEach(b=>b.onclick=()=>reviewLicense(b.dataset.reject,'rejected'))}
async function reviewLicense(id,status){let label=status==='active'?'approve and activate':'reject';if(!confirm(`Are you sure you want to ${label} this license payment request?`))return;try{await api('platform/license/'+id,{method:'PATCH',body:JSON.stringify({status,reviewNote:''})});toast(status==='active'?'License approved and activated.':'License rejected.');await ownerPage('licenses')}catch(e){console.error(e);toast('License action failed: '+e.message)}}
async function ownerPlans(){let rows=await api('platform/license-plans');$('#page').innerHTML=title('License plan catalogue','<button id="addPlan">+ Post license plan</button>')+`<section class="panel"><p class="muted">Publish the plans administrators see in their Purchase License tab. A price of 0 creates an instant free license with no payment form.</p><div class="tablewrap"><table><thead><tr><th>Title</th><th>Duration</th><th>Shop slots</th><th>Price</th><th>ConnectX</th><th>Active</th><th>Benefits</th><th>Action</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(p.title)}</td><td>${p.duration_months} months</td><td>${p.max_stores}</td><td>${money(p.price)}</td><td>${p.connectx_enabled?`${p.connectx_daily_limit}/shop/day`:'No'}</td><td>${p.active?'Yes':'No'}</td><td>${esc(p.benefits)}</td><td><button class="secondary" data-edit-plan="${p.id}">Edit</button></td></tr>`).join('')}</tbody></table></div></section>`;$('#addPlan').onclick=()=>planModal();document.querySelectorAll('[data-edit-plan]').forEach(x=>x.onclick=()=>planModal(rows.find(p=>p.id===x.dataset.editPlan)))}
function planModal(plan=null){let add=!plan,e=document.createElement('div');e.className='modal';e.innerHTML=`<form class="modalbox fields"><div class="modalhead"><h2>${add?'Post license plan':'Edit license plan'}</h2><button type="button">×</button></div><label>Plan title<input name="title" required value="${esc(plan?.title||'')}"></label><div class="grid2"><label>Duration (months)<input name="duration_months" type="number" min="1" required value="${esc(plan?.duration_months||'')}"></label><label>Total shop create limit<input name="max_stores" type="number" min="1" required value="${esc(plan?.max_stores||1)}"></label><label>Price (BDT; enter 0 for free)<input name="price" type="number" min="0" step="0.01" required value="${esc(plan?.price??0)}"></label><label>Availability<select name="active"><option value="true" ${plan?.active!==false?'selected':''}>Published</option><option value="false" ${plan?.active===false?'selected':''}>Hidden</option></select></label></div><section class="cxPlanEntitlement"><label class="toggleEntitlement"><span>Include ConnectX</span><span class="planFeatureToggle"><b>Off</b><input name="connectx_enabled" type="checkbox" ${plan?.connectx_enabled?'checked':''}><i></i><b>On</b></span></label><label>ConnectX emails per shop / day<input name="connectx_daily_limit" type="number" min="0" value="${esc(plan?.connectx_daily_limit??0)}"></label></section><section class="cxPlanEntitlement"><label class="toggleEntitlement"><span>Include Zudo</span><span class="planFeatureToggle"><b>Off</b><input name="zudo_enabled" type="checkbox" ${plan?.zudo_enabled?'checked':''}><i></i><b>On</b></span></label><label>Zudo requests per shop / day<input name="zudo_daily_limit" type="number" min="0" value="${esc(plan?.zudo_daily_limit??0)}"></label></section><section class="cxPlanEntitlement"><label class="toggleEntitlement"><span>Include Business AI Health</span><span class="planFeatureToggle"><b>Off</b><input name="business_health_enabled" type="checkbox" ${plan?.business_health_enabled?'checked':''}><i></i><b>On</b></span></label><label>Business AI Health reports per shop / day<input name="business_health_daily_limit" type="number" min="0" value="${esc(plan?.business_health_daily_limit??0)}"></label></section><label>Benefits / information<textarea name="benefits" required>${esc(plan?.benefits||'')}</textarea></label><label>Payment instructions/details<textarea name="payment_details">${esc(plan?.payment_details||'')}</textarea></label><button>${add?'Publish license plan':'Save plan'}</button></form>`;document.body.append(e);e.querySelector('[type=button]').onclick=()=>e.remove();e.querySelector('form').onsubmit=async ev=>{ev.preventDefault();try{let b=Object.fromEntries(new FormData(ev.target));b.duration_months=+b.duration_months;b.max_stores=+b.max_stores;b.price=+b.price;b.active=b.active==='true';b.connectx_enabled=e.querySelector('[name=connectx_enabled]').checked;b.connectx_daily_limit=+b.connectx_daily_limit||0;b.zudo_enabled=e.querySelector('[name=zudo_enabled]').checked;b.zudo_daily_limit=+b.zudo_daily_limit||0;b.business_health_enabled=e.querySelector('[name=business_health_enabled]').checked;b.business_health_daily_limit=+b.business_health_daily_limit||0;await api(add?'platform/license-plans':'platform/license-plan/'+plan.id,{method:add?'POST':'PATCH',body:JSON.stringify(b)});e.remove();toast('License plan saved.');ownerPlans()}catch(x){toast(x.message)}}}
function ownerAdmins(d){$('#page').innerHTML=title('Administrator control')+`<section class="panel"><p class="muted">Deactivating an administrator blocks new administrator sign-ins. Existing sessions expire automatically.</p><div class="tablewrap"><table><thead><tr><th>Administrator ID</th><th>Name</th><th>Email</th><th>Phone</th><th>Created</th><th>Status</th><th>Action</th></tr></thead><tbody>${d.admins.map(x=>`<tr><td><code class="shopid">${esc(x.admin_code)}</code></td><td>${esc(x.name)}</td><td>${esc(x.email)}</td><td>${esc(x.phone)}</td><td>${esc(x.created_at)}</td><td><span class="statuspill ${x.active?'active':'inactive'}">${x.active?'Active':'Inactive'}</span></td><td><button class="secondary" data-admin-state="${x.id}" data-active="${x.active}">${x.active?'Deactivate':'Activate'}</button></td></tr>`).join('')}</tbody></table></div></section>`;document.querySelectorAll('[data-admin-state]').forEach(b=>b.onclick=async()=>{try{await api('platform/administrator/'+b.dataset.adminState,{method:'PATCH',body:JSON.stringify({active:b.dataset.active!=='true'})});toast('Administrator status changed.');ownerPage('administrators')}catch(e){toast(e.message)}})}
function ownerShops(d){$('#page').innerHTML=title('All shops')+`<section class="panel"><div class="tablewrap"><table><thead><tr><th>Shop</th><th>Shop ID</th><th>Administrator</th><th>Administrator ID</th><th>Email</th><th>Status</th><th>Created</th></tr></thead><tbody>${d.stores.map(x=>`<tr><td>${esc(x.name)}</td><td><code class="shopid">${esc(x.shop_code)}</code></td><td>${esc(x.administrators?.name)}</td><td><code class="shopid">${esc(x.administrators?.admin_code)}</code></td><td>${esc(x.administrators?.email)}</td><td><span class="statuspill ${x.status==='active'?'active':'inactive'}">${x.status}</span></td><td>${esc(x.created_at)}</td></tr>`).join('')}</tbody></table></div></section>`}
async function ownerBranding(){let b=await api('platform/settings');$('#page').innerHTML=title('Website branding')+`<form class="panel fields" id="brandForm"><p class="muted">These fields are reserved for the EMS public website identity. They do not alter customer shop records.</p><label>Website name<input name="website_name" required value="${esc(b.website_name||'EMS V1')}"></label><label>Product name<input name="product_name" required value="${esc(b.product_name||'EMS V1')}"></label><label>Powered by<input name="powered_by" required value="${esc(b.powered_by||'DoxTox')}"></label><label>Public production website URL <span class="muted">Used in invoice verification QR codes. Example: https://ems.example.com</span><input name="public_base_url" type="url" value="${esc(b.public_base_url||'')}"></label><button>Save website details</button></form>`;$('#brandForm').onsubmit=async e=>{e.preventDefault();try{await api('platform/settings',{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});toast('Website branding saved.')}catch(x){toast(x.message)}}}
async function ownerTheme(){let p=await api('platform/theme'),fields=[['classic_ink','Main Ink','#172536'],['classic_navy','Navy','#173b59'],['classic_navy_deep','Deep Navy','#102d45'],['classic_slate','Slate Text','#607184'],['classic_cream','Cream Background','#f7f4ee'],['classic_paper','Paper Surface','#fffdfa'],['classic_line','Border','#e2ddd3'],['classic_teal','Teal Accent','#2f806f'],['classic_teal_dark','Deep Teal','#236456'],['classic_gold','Gold Accent','#c8954e'],['classic_red','Danger Red','#b64f4b']];$('#page').innerHTML=title('Theme palette')+`<form class="themeEditor rustPalette" id="themeEditor"><p class="muted">Modern Classic palette. Changes apply to the full public website and all dashboards. No theme packages are enabled.</p><section><h2>Modern Classic Colors</h2><div class="themeFields">${fields.map(([key,label,def])=>`<label>${label}<span><input type="color" name="${key}" value="${esc(p[key]||def)}"><input class="themeHex" name="${key}_hex" value="${esc(p[key]||def)}"></span></label>`).join('')}</div></section><button>Save Modern Classic palette</button></form>`;let form=$('#themeEditor'),preview=()=>applyPalette({...p,...Object.fromEntries([...form.querySelectorAll('input[type=color]')].map(x=>[x.name,x.value]))});form.querySelectorAll('input[type=color]').forEach(c=>c.oninput=()=>{form.elements[c.name+'_hex'].value=c.value;preview()});form.querySelectorAll('.themeHex').forEach(x=>x.onchange=()=>{let key=x.name.replace('_hex','');if(/^#[0-9a-fA-F]{6}$/.test(x.value)){form.elements[key].value=x.value;preview()}});form.onsubmit=async e=>{e.preventDefault();let data=Object.fromEntries([...form.querySelectorAll('input[type=color]')].map(x=>[x.name,x.value]));try{await api('platform/theme',{method:'PATCH',body:JSON.stringify(data)});applyPalette(data);toast('Modern Classic palette applied.')}catch(err){toast(err.message)}}}
async function ownerWebsitePages(){let pages=await api('platform/pages'),standard=[['about','About EMS V1'],['terms','Terms & Conditions'],['contact','Contact Us']],bySlug=Object.fromEntries(pages.map(x=>[x.slug,x]));$('#page').innerHTML=title('Website pages','<button id="addMissingPages">+ Add missing standard pages</button>')+`<section class="panel"><p class="muted">Manage the fixed public About, Terms & Conditions and Contact pages.</p><div class="tablewrap"><table><thead><tr><th>Page</th><th>URL page</th><th>Status</th><th>Action</th></tr></thead><tbody>${standard.map(([slug,label])=>{let page=bySlug[slug];return `<tr><td>${esc(page?.title||label)}</td><td>/${slug}</td><td>${page?'Available':'Missing'}</td><td>${page?`<button class="secondary" data-edit-page="${slug}">Edit page</button>`:`<button data-add-page="${slug}">Add page</button>`}</td></tr>`}).join('')}</tbody></table></div><div id="websitePageEditors">${pages.map(p=>`<details class="cmsPage" data-page-editor="${p.slug}"><summary><span>${esc(p.title)} <small>${esc(p.slug)}</small></span><button type="button" class="secondary cmsEditButton" data-edit-page="${esc(p.slug)}">Edit page</button></summary><form data-cms-page="${p.slug}" class="fields"><label>Page title<input name="title" value="${esc(p.title)}"></label>${p.slug==='about'?'<label>Graphics prompt / note<input name="hero_image_prompt" value="'+esc(p.hero_image_prompt||'')+'"></label>':''}<label>Page content<textarea name="body" rows="12">${esc(p.body)}</textarea></label><button>Save page</button></form></details>`).join('')}</div></section>`;let add=async slug=>{try{await api('platform/pages',{method:'POST',body:JSON.stringify({slug})});toast('Standard page added.');ownerWebsitePages()}catch(e){toast(e.message)}};$('#addMissingPages').onclick=async()=>{let missing=standard.filter(([slug])=>!bySlug[slug]);if(!missing.length)return toast('All standard public pages already exist.');for(let [slug] of missing)await add(slug)};document.querySelectorAll('[data-add-page]').forEach(x=>x.onclick=()=>add(x.dataset.addPage));document.querySelectorAll('[data-edit-page]').forEach(btn=>btn.onclick=e=>{e.preventDefault();e.stopPropagation();let d=document.querySelector(`[data-page-editor="${btn.dataset.editPage}"]`);if(d){d.open=true;d.scrollIntoView({behavior:'smooth',block:'start'})}});document.querySelectorAll('[data-cms-page]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{let b=Object.fromEntries(new FormData(e.target));b.slug=e.target.dataset.cmsPage;await api('platform/pages',{method:'PATCH',body:JSON.stringify(b)});toast('Public page saved.')}catch(err){toast(err.message)}})}
async function ownerBlogs(){let rows=await api('platform/blogs');$('#page').innerHTML=title('Blog posts','<button id="addBlog">+ New blog post</button>')+`<section class="panel"><div class="tablewrap"><table><thead><tr><th>Title</th><th>Status</th><th>Published</th><th>Action</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.title)}</td><td>${x.published?'Published':'Draft'}</td><td>${x.published_at?new Date(x.published_at).toLocaleDateString():'—'}</td><td><button class="secondary" data-blog-edit="${x.id}">Edit</button></td></tr>`).join('')}</tbody></table></div></section>`;$('#addBlog').onclick=()=>blogModal();document.querySelectorAll('[data-blog-edit]').forEach(b=>b.onclick=()=>blogModal(rows.find(x=>x.id===b.dataset.blogEdit)))}
function blogModal(post=null){let e=document.createElement('div');e.className='modal';e.innerHTML=`<form class="modalbox fields"><div class="modalhead"><h2>${post?'Edit':'New'} blog post</h2><button type="button">×</button></div><label>Title<input name="title" required value="${esc(post?.title||'')}"></label><label>Excerpt<input name="excerpt" value="${esc(post?.excerpt||'')}"></label><label>Cover image URL<input name="cover_image_url" value="${esc(post?.cover_image_url||'')}"></label><label>Article content<textarea name="body" rows="14" required>${esc(post?.body||'')}</textarea></label><label>Publication status<select name="published"><option value="false" ${!post?.published?'selected':''}>Draft</option><option value="true" ${post?.published?'selected':''}>Published</option></select></label><button>Save blog post</button></form>`;document.body.append(e);e.querySelector('[type=button]').onclick=()=>e.remove();e.querySelector('form').onsubmit=async ev=>{ev.preventDefault();let b=Object.fromEntries(new FormData(ev.target));b.published=b.published==='true';try{await api(post?'platform/blog/'+post.id:'platform/blogs',{method:post?'PATCH':'POST',body:JSON.stringify(b)});e.remove();toast('Blog post saved.');ownerBlogs()}catch(err){toast(err.message)}}}
