async function settings(){let tab='store';$('#page').innerHTML=title('Settings')+`<div class="settingtabs"><button class="on" data-setting-tab="store">Store</button><button data-setting-tab="activity">Activity Log</button></div><div id="settingContent"></div>`;async function render(){let el=$('#settingContent');el.innerHTML='<section class="panel"><p class="muted">Loading…</p></section>';if(tab==='store'){let x=await api('shop/settings');el.innerHTML=`<section class="storeDetails"><div><span>Store name</span><b>${esc(x.name)}</b></div><div><span>Shop ID</span><b><code class="shopid">${esc(x.shop_code)}</code></b></div><div><span>Address</span><b>${esc(x.address||'—')}</b></div><div><span>Phone</span><b>${esc(x.phone||'—')}${x.phone2?' / '+esc(x.phone2):''}</b></div><div><span>Email</span><b>${esc(x.email||'—')}</b></div><div><span>Website</span><b>${esc(x.website||'—')}</b></div><div><span>Low stock alert</span><b>${esc(x.low_stock_threshold)}</b></div><div><span>Status</span><b><span class="statuspill ${x.status==='active'?'active':'inactive'}">${esc(x.status)}</span></b></div></section>`}else{let logs=await api('shop/activity-logs');el.innerHTML=`<section class="panel"><div class="loghead"><div><h2>Activity Log</h2><p class="muted">Login, create, update, delete, and recovery activity for this shop.</p></div><input id="logSearch" placeholder="Search activity"></div><div id="logTable">${activityTable(logs)}</div></section>`;$('#logSearch').oninput=e=>$('#logTable').innerHTML=activityTable(logs.filter(x=>JSON.stringify(x).toLowerCase().includes(e.target.value.toLowerCase())))}}function activityTable(rows){return rows.length?`<div class="tablewrap"><table><thead><tr><th>Action</th><th>Entity</th><th>Details</th><th>User ID</th><th>User</th><th>Date & time</th></tr></thead><tbody>${rows.map(x=>`<tr><td><span class="logaction">${esc(x.action)}</span></td><td>${esc(x.entity_type||'—')}</td><td><code class="shopid">${esc(x.detail||'—')}</code></td><td>${esc(x.actor?.userId||'—')}</td><td>${esc(x.actor?.name||'—')}</td><td>${new Date(x.created_at).toLocaleString()}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No activity has been recorded for this shop.</p>'}document.querySelectorAll('[data-setting-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.settingTab;document.querySelectorAll('[data-setting-tab]').forEach(x=>x.classList.toggle('on',x===b));render()});await render()}
function modal(head,fields,submit){let e=document.createElement('div');e.className='modal';e.innerHTML=`<form class="modalbox fields"><div class="modalhead"><h2>${head}</h2><button type="button">×</button></div>${fields.map(([n,l,r])=>`<label>${l}<input name="${n}" ${r?'required':''}></label>`).join('')}<button>Save</button></form>`;document.body.append(e);e.querySelector('[type=button]').onclick=()=>e.remove();e.querySelector('form').onsubmit=async x=>{x.preventDefault();try{await submit(Object.fromEntries(new FormData(x.target)));e.remove()}catch(err){toast(err.message)}}}
api('public/theme').then(applyPalette).catch(()=>{});if(new URLSearchParams(location.search).get('verify')){verificationPage(new URLSearchParams(location.search).get('verify'))}else if(new URLSearchParams(location.search).get('page')){publicPage(new URLSearchParams(location.search).get('page'))}else if(state){scheduleLogout();home()}else login();

/* ===== Premium Add-Ons ===== */
let addonCart=[],addonCoupon=null;
const ADDON_NAMES={connectx:'ConnectX',zudo:'Zudo AI',business_health:'AI Business Health'};
const addonName=x=>x.title||ADDON_NAMES[x.addon_key]||x.addon_key;
const addonIcon=k=>k==='connectx'?'✉':k==='zudo'?'✦':'▥';
const addonArt=x=>`<div class="addonArt">${x.image_url?`<img src="${esc(x.image_url)}" alt="" loading="lazy" onerror="this.remove()">`:''}<i>${addonIcon(x.addon_key)}</i></div>`;
const addonBadgeCls=st=>st==='active'?'act':st==='pending'?'pend':st==='rejected'?'rej':st==='expired'?'exp':'';

async function premiumAddons(){
  const d=await api('addons'),now=Date.now(),ent=d.entitlement||null,purchases=d.purchases||[];
  const cartKeys=()=>addonCart.map(i=>i.addon_key);
  function statusOf(x){
    if(!x.enabled)return {key:'disabled',label:'Inactive',cls:'off'};
    if(ent&&((x.addon_key==='connectx'&&ent.connectx_enabled)||(x.addon_key==='zudo'&&ent.zudo_enabled)||(x.addon_key==='business_health'&&ent.business_health_enabled)))return {key:'included',label:'Included in license',cls:'inc'};
    const act=purchases.find(p=>p.addon_key===x.addon_key&&p.status==='active'&&new Date(p.expires_at)>now);
    if(act)return {key:'active',label:'Active until '+new Date(act.expires_at).toLocaleDateString(),cls:'act'};
    const pend=purchases.find(p=>p.addon_key===x.addon_key&&p.status==='pending');
    if(pend)return {key:'pending',label:'Pending review',cls:'pend'};
    if(cartKeys().includes(x.addon_key))return {key:'incart',label:'In cart',cls:'cart'};
    return {key:'buy',label:'Available',cls:'ok'};
  }
  function buttonFor(st){return st.key==='incart'?'In cart':st.key==='included'?'Included':st.key==='active'?'Active':st.key==='pending'?'Pending':st.key==='disabled'?'Inactive':'Add to cart';}
  const money=v=>Number(v||0).toLocaleString('en-BD');
  const draw=()=>{
    const sub=addonCart.reduce((n,i)=>n+i.validity_days*i.daily_limit*i.unit_price,0);
    const discount=addonCoupon?Math.round(sub*addonCoupon.percent_off)/100:0;
    const grand=sub-discount;
    $('#page').innerHTML=title('Premium Add-Ons')+`<div class="addonShop"><div><section class="addonGrid">${d.settings.map(x=>{const st=statusOf(x);return `<article class="addonCard">${addonArt(x)}<h2>${esc(addonName(x))}</h2><p>${esc(x.details||'')}</p><small class="statusBadge ${st.cls}">${esc(st.label)}</small><button data-buy-addon="${x.addon_key}" ${st.key==='buy'?'':'disabled'}>${buttonFor(st)}</button></article>`}).join('')}</section></div>${addonCart.length?`<aside class="addonCheckout"><h2>Checkout</h2>${addonCart.map((i,n)=>`<div class="cartItem"><span>${esc(addonName(i))}<small>${i.daily_limit}/day · ${i.validity_days} days</small></span><b>${money(i.validity_days*i.daily_limit*i.unit_price)} BDT</b><button class="danger" data-remove-cart="${n}" title="Remove">×</button></div>`).join('')}<div class="cartTotals"><p><span>Subtotal</span><b id="addonSub">${money(sub)} BDT</b></p><div class="couponRow"><input id="addonCoupon" placeholder="Coupon code" ${addonCoupon?`value="${esc(addonCoupon.code)}" readonly`:''}>${addonCoupon?`<button type="button" id="addonCouponClear" class="ghost">Clear</button>`:`<button type="button" id="addonCouponApply">Apply</button>`}</div>${addonCoupon?`<p><span>Coupon (${esc(addonCoupon.code)} −${addonCoupon.percent_off}%)</span><b>−${money(discount)} BDT</b></p>`:''}<p class="grand"><span>Grand Total</span><b id="addonGrand">${money(grand)} BDT</b></p></div>${d.payment_info?`<div class="paymentInfo"><h3>Payment instructions</h3><p>${esc(d.payment_info).replace(/\n/g,'<br>')}</p></div>`:''}<label>Payment method<select id="addonPay"><option value="bkash">bKash</option><option value="nagad">Nagad</option></select></label><label>Payment number<input id="addonPayNumber" placeholder="Required" required></label><label>Transaction ID<input id="addonTrx" placeholder="Required" required></label><button id="addonConfirm">Confirm purchase</button></aside>`:''}</div><section class="panel addonHistory"><h2>Purchase history</h2>${purchases.length?`<div class="tablewrap"><table><thead><tr><th>Add-on</th><th>Days</th><th>Daily limit</th><th>Amount</th><th>Discount</th><th>Payable</th><th>Payment</th><th>Transaction ID</th><th>Status</th><th>Expiry</th></tr></thead><tbody>${purchases.map(p=>`<tr><td>${esc(ADDON_NAMES[p.addon_key]||p.addon_key)}</td><td>${p.validity_days}</td><td>${p.daily_limit}</td><td>${money(p.amount)} BDT</td><td>${Number(p.discount_amount||0)?'−'+money(p.discount_amount)+' BDT':'—'}</td><td><b>${money(Math.max(0,Number(p.amount||0)-Number(p.discount_amount||0)))} BDT</b></td><td>${esc(p.payment_method)}<br><small>${esc(p.payment_number)}</small></td><td>${esc(p.transaction_id)}</td><td><span class="statusBadge ${addonBadgeCls(p.status)}">${esc(p.status)}</span></td><td>${p.expires_at?new Date(p.expires_at).toLocaleDateString():'—'}</td></tr>`).join('')}</tbody></table></div>`:`<p class="muted">No purchases yet.</p>`}</section>`;
    document.querySelectorAll('[data-buy-addon]').forEach(b=>b.onclick=()=>addonCartModal(d.settings.find(x=>x.addon_key===b.dataset.buyAddon),draw));
    document.querySelectorAll('[data-remove-cart]').forEach(b=>b.onclick=()=>{addonCart.splice(+b.dataset.removeCart,1);addonCoupon=null;draw()});
    const applyBtn=$('#addonCouponApply');
    if(applyBtn)applyBtn.onclick=async()=>{try{const r=await api('addons/coupon?code='+encodeURIComponent($('#addonCoupon').value));addonCoupon={code:r.code,percent_off:r.percent_off};toast('Coupon applied: −'+r.percent_off+'%');}catch(e){addonCoupon=null;toast(e.message)}draw()};
    const clearBtn=$('#addonCouponClear');
    if(clearBtn)clearBtn.onclick=()=>{addonCoupon=null;draw()};
    const conf=$('#addonConfirm');
    if(conf)conf.onclick=async()=>{const payMethod=$('#addonPay').value,payNumber=$('#addonPayNumber').value.trim(),trx=$('#addonTrx').value.trim();if(!addonCart.length)return toast('Your cart is empty.');if(!payNumber)return toast('Payment number is required.');if(!trx)return toast('Transaction ID is required.');try{await api('addon-checkout',{method:'POST',body:JSON.stringify({items:addonCart,payment_method:payMethod,payment_number:payNumber,transaction_id:trx,coupon:addonCoupon?addonCoupon.code:''})});addonCart=[];addonCoupon=null;toast('Purchase request submitted.');premiumAddons()}catch(e){toast(e.message)}};
  };
  draw();
}

function addonCartModal(x,refresh){
  const e=document.createElement('div');e.className='modal';
  e.innerHTML=`<form class="modalbox fields"><div class="modalhead"><h2>${esc(addonName(x))}</h2><button type="button">×</button></div><p>${esc(x.details||'')}</p><p class="muted">Price = validity days × daily limit × ${Number(x.unit_price).toLocaleString('en-BD')} BDT</p><div class="grid2"><label>Validity days<input id="ad" type="number" min="${x.min_days}" max="${x.max_days}" value="${x.min_days}" required></label><label>Daily limit<input id="al" type="number" min="${x.min_daily_limit}" max="${x.max_daily_limit}" value="${x.min_daily_limit}" required></label></div><p class="addonModalTotal"><span>Total</span><b id="at"></b></p><button>Add to cart</button></form>`;
  document.body.append(e);
  const calc=()=>$('#at').textContent=(+$('#ad').value*+$('#al').value*Number(x.unit_price)).toLocaleString('en-BD')+' BDT';
  calc();$('#ad').oninput=calc;$('#al').oninput=calc;
  e.querySelector('[type=button]').onclick=()=>e.remove();
  e.querySelector('form').onsubmit=v=>{v.preventDefault();const days=+$('#ad').value,limit=+$('#al').value;if(days<x.min_days||days>x.max_days)return toast('Validity days must be between '+x.min_days+' and '+x.max_days+'.');if(limit<x.min_daily_limit||limit>x.max_daily_limit)return toast('Daily limit must be between '+x.min_daily_limit+' and '+x.max_daily_limit+'.');addonCart=addonCart.filter(i=>i.addon_key!==x.addon_key);addonCart.push({addon_key:x.addon_key,title:x.title,validity_days:days,daily_limit:limit,unit_price:Number(x.unit_price)});addonCoupon=null;e.remove();refresh()};
}

async function ownerAddons(){
  const [settings,purchases]=await Promise.all([api('platform/addons'),api('platform/addon-purchases')]);
  const money=v=>Number(v||0).toLocaleString('en-BD');
  $('#page').innerHTML=title('Premium Add-Ons','<button id="addonCheckoutSetup">Payment & coupon setup</button>')+`<section class="addonGrid owner">${settings.map(x=>`<article class="addonCard">${addonArt(x)}<h2>${esc(addonName(x))}</h2><p>${esc(x.details||'Configure this add-on.')}</p><small>${x.enabled?'Active':'Inactive'}</small><button data-addon-setup="${x.addon_key}">Setup</button></article>`).join('')}</section><section class="panel addonHistory"><h2>Purchase requests</h2>${purchases.length?`<div class="tablewrap"><table><thead><tr><th>Admin</th><th>Add-on</th><th>Days</th><th>Daily limit</th><th>Amount</th><th>Discount</th><th>Payable</th><th>Payment</th><th>Transaction ID</th><th>Coupon</th><th>Requested</th><th>Status</th><th>Action</th></tr></thead><tbody>${purchases.map(x=>`<tr><td>${esc(x.administrators?.name||'—')}<br><small class="muted">${x.administrators?.admin_code?('#'+esc(x.administrators.admin_code)):''}</small></td><td>${esc(ADDON_NAMES[x.addon_key]||x.addon_key)}</td><td>${x.validity_days}</td><td>${x.daily_limit}</td><td>${money(x.amount)} BDT</td><td>${Number(x.discount_amount||0)?'−'+money(x.discount_amount)+' BDT':'—'}</td><td><b>${money(Math.max(0,Number(x.amount||0)-Number(x.discount_amount||0)))} BDT</b></td><td>${esc(x.payment_method)}<br><small>${esc(x.payment_number)}</small></td><td>${esc(x.transaction_id)}</td><td>${esc(x.coupon_code||'—')}</td><td>${new Date(x.created_at).toLocaleDateString()}</td><td><span class="statusBadge ${addonBadgeCls(x.status)}">${esc(x.status)}</span></td><td>${x.status==='pending'?`<button data-addon-review="${x.id}" data-status="active">Approve</button> <button class="danger" data-addon-review="${x.id}" data-status="rejected">Reject</button>`:'Reviewed'}</td></tr>`).join('')}</tbody></table></div>`:`<p class="muted">No purchase requests yet.</p>`}</section>`;
  $('#addonCheckoutSetup').onclick=async()=>{try{const d=await api('platform/addon-checkout');const e=document.createElement('div');e.className='modal';e.innerHTML=`<div class="modalbox"><div class="modalhead"><h2>Payment & coupon setup</h2><button type="button" id="cpClose">×</button></div><form class="fields" id="cpPayForm"><h3>Checkout payment instructions</h3><label>Instructions shown to administrators at checkout<textarea name="payment_info" rows="3">${esc(d.settings?.payment_info||'')}</textarea></label><button>Save payment instructions</button></form><hr><div class="cpCoupons"><h3>Coupon codes</h3><div id="cpCouponList" class="cpCouponList"></div><form class="cpAddRow" id="cpAddForm"><input name="code" placeholder="COUPON CODE" maxlength="20"><input name="percent_off" type="number" min="1" max="100" placeholder="%"><button type="submit">Add coupon</button></form></div></div>`;document.body.append(e);e.querySelector('#cpClose').onclick=()=>e.remove();const renderCoupons=()=>{const box=e.querySelector('#cpCouponList');box.innerHTML=d.coupons.length?d.coupons.map(c=>`<div class="cpRow ${c.active?'':'off'}"><div class="cpCode"><b>${esc(c.code)}</b><small>${c.percent_off}% off</small></div><div class="cpActions"><button type="button" class="cpToggle ${c.active?'on':'off'}" data-cp-toggle="${esc(c.code)}">${c.active?'Active':'Inactive'}</button><button type="button" class="danger cpDel" data-cp-del="${esc(c.code)}">Delete</button></div></div>`).join(''):'<p class="muted">No coupons yet.</p>';box.querySelectorAll('[data-cp-toggle]').forEach(b=>b.onclick=async()=>{const code=b.dataset.cpToggle,cur=d.coupons.find(c=>c.code===code);try{await api('platform/addon-coupons',{method:'PATCH',body:JSON.stringify({code,active:!cur.active})});cur.active=!cur.active;renderCoupons();toast('Coupon '+(cur.active?'activated':'deactivated')+'.')}catch(err){toast(err.message)}});box.querySelectorAll('[data-cp-del]').forEach(b=>b.onclick=async()=>{const code=b.dataset.cpDel;if(!confirm('Delete coupon '+code+'?'))return;try{await api('platform/addon-coupons?code='+encodeURIComponent(code),{method:'DELETE'});d.coupons=d.coupons.filter(c=>c.code!==code);renderCoupons();toast('Coupon deleted.')}catch(err){toast(err.message)}})};renderCoupons();e.querySelector('#cpPayForm').onsubmit=async ev=>{ev.preventDefault();const b=Object.fromEntries(new FormData(ev.target));try{await api('platform/addon-checkout',{method:'PATCH',body:JSON.stringify({payment_info:b.payment_info})});toast('Payment instructions saved.')}catch(err){toast(err.message)}};e.querySelector('#cpAddForm').onsubmit=async ev=>{ev.preventDefault();const b=Object.fromEntries(new FormData(ev.target));try{const x=await api('platform/addon-coupons',{method:'POST',body:JSON.stringify({code:b.code,percent_off:+b.percent_off,active:true})});d.coupons.unshift(x);renderCoupons();ev.target.reset();toast('Coupon added.')}catch(err){toast(err.message)}}}catch(err){toast(err.message)}};
  document.querySelectorAll('[data-addon-setup]').forEach(b=>b.onclick=()=>addonSetup(settings.find(x=>x.addon_key===b.dataset.addonSetup)));
  document.querySelectorAll('[data-addon-review]').forEach(b=>b.onclick=async()=>{try{await api('platform/addon-purchases',{method:'PATCH',body:JSON.stringify({id:b.dataset.addonReview,status:b.dataset.status})});toast('Purchase reviewed.');ownerAddons()}catch(e){toast(e.message)}});
}

function addonSetup(x){
  const e=document.createElement('div');e.className='modal';
  e.innerHTML=`<form class="modalbox fields"><div class="modalhead"><h2>${esc(addonName(x))} setup</h2><button type="button">×</button></div><label>Title<input name="title" value="${esc(x.title||'')}" placeholder="${esc(ADDON_NAMES[x.addon_key]||'')}"></label><label>Image URL (PNG)<input name="image_url" type="url" value="${esc(x.image_url||'')}" placeholder="https://example.com/addon.png"></label><label>Status<select name="enabled"><option value="true" ${x.enabled?'selected':''}>Active</option><option value="false" ${!x.enabled?'selected':''}>Inactive</option></select></label><label>Details<textarea name="details">${esc(x.details)}</textarea></label><div class="grid2"><label>Unit price<input name="unit_price" type="number" step=".01" value="${x.unit_price}"></label><label>Minimum days<input name="min_days" type="number" value="${x.min_days}"></label><label>Maximum days<input name="max_days" type="number" value="${x.max_days}"></label><label>Minimum daily limit<input name="min_daily_limit" type="number" value="${x.min_daily_limit}"></label><label>Maximum daily limit<input name="max_daily_limit" type="number" value="${x.max_daily_limit}"></label></div><button>Save setup</button></form>`;
  document.body.append(e);e.querySelector('[type=button]').onclick=()=>e.remove();
  e.querySelector('form').onsubmit=async ev=>{ev.preventDefault();const b=Object.fromEntries(new FormData(ev.target));Object.assign(b,{addon_key:x.addon_key,title:b.title,image_url:b.image_url?String(b.image_url).trim():null,enabled:b.enabled==='true',unit_price:+b.unit_price,min_days:+b.min_days,max_days:+b.max_days,min_daily_limit:+b.min_daily_limit,max_daily_limit:+b.max_daily_limit});try{await api('platform/addons',{method:'PATCH',body:JSON.stringify(b)});e.remove();toast('Add-on setup saved.');ownerAddons()}catch(err){toast(err.message)}};
}
